//! ML-DSA-87 instantiation (FIPS 204 §4 Table 1).
//!
//! Parameters: λ=256, τ=60, γ₁=2¹⁹, γ₂=(q−1)/32, k=8, ℓ=7, η=2, β=120, ω=75.
//! Sizes: PK_LEN=2592, SK_LEN=4896, SIG_LEN=4627, CTILDE_LEN=64.
//!
//! Generated by the `ml_dsa_impl!` macro.
//!
//! # CNSA gating
//!
//! ML-DSA-87 is the CNSA 2.0 digital-signature mandate (CNSSP 15).
//! The `Service::MlDsa87Sign` / `Verify` / `Keygen` / `ExpandKey` variants are
//! permitted under [`oxicrypt_module::AlgorithmProfile::Unrestricted`],
//! `Cnsa2` and `Migration`, and refused under `Cnsa1`.

#![allow(
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::cast_possible_truncation,
    clippy::cast_lossless,
    clippy::cast_possible_wrap,
    clippy::cast_sign_loss,
    clippy::similar_names,
    clippy::many_single_char_names,
    clippy::needless_range_loop,
    clippy::integer_division,
    clippy::too_many_lines,
    dead_code
)]

crate::ml_dsa_impl::ml_dsa_impl! {
    lambda = 256;
    tau = 60;
    gamma1 = 1 << 19;
    gamma2 = (8_380_417 - 1) / 32;
    k = 8;
    l = 7;
    eta = 2;
    beta = 120;
    omega = 75;
    svc_keygen = Service::MlDsa87Keygen;
    svc_expand_key = Service::MlDsa87ExpandKey;
    svc_sign = Service::MlDsa87Sign;
    svc_verify = Service::MlDsa87Verify;
    rbg_strength_bits = 256;
    pct_reason = "ML-DSA-87 pairwise consistency";
}

#[cfg(test)]
#[allow(
    clippy::unwrap_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects
)]
mod tests {
    use super::*;

    /// FIPS 204 §3.6.1: at least 256 bits for ML-DSA-87, so CTR_DRBG with
    /// AES-192 is refused, before its draw would report it uninstantiated.
    #[test]
    fn strength_floor_is_256() {
        let refused = Err(Error::RbgTooWeak);
        assert_eq!(rbg_services::with_strength(255), (refused, refused, 0));
        assert_eq!(rbg_services::with_strength(256), (Ok(()), Ok(()), 2));
        let mut aes192 = oxicrypt_drbg::CtrDrbgAes192::new();
        assert_eq!(keygen(&mut aes192).map(drop), Err(Error::RbgTooWeak));
        assert_eq!(
            keygen_with_seed(&mut aes192).map(drop),
            Err(Error::RbgTooWeak)
        );
    }

    /// ACVP ML-DSA-87 keyGen, tgId 3, tcId 51.
    #[test]
    fn expand_key_reproduces_acvp_vector() {
        use crate::cast_vectors::ml_dsa_87 as v;
        crate::test_support::start_module();
        let (pk, sk) = expand_key(&v::KEYGEN_XI).unwrap();
        assert_eq!(
            &pk[..],
            include_bytes!("../tests/data/mldsa87_nist_keygen_pk.bin")
        );
        assert_eq!(sk, v::KEYGEN_SK);
    }

    #[test]
    fn key_sizes_match_spec() {
        crate::test_support::start_module();
        assert_eq!(PK_LEN, 2592);
        assert_eq!(SK_LEN, 4896);
        assert_eq!(SIG_LEN, 4627);
        assert_eq!(CTILDE_LEN, 64);
    }

    #[test]
    fn parameter_constants_match_spec() {
        crate::test_support::start_module();
        assert_eq!(K, 8);
        assert_eq!(L, 7);
        assert_eq!(ETA, 2);
        assert_eq!(TAU, 60);
        assert_eq!(BETA, 120);
        assert_eq!(OMEGA, 75);
    }

    #[test]
    fn round_trip_basic() {
        crate::test_support::start_module();
        let xi = [0x42u8; 32];
        let (pk, sk) = keygen_internal_guarded(&xi).unwrap();
        let msg = b"hello, ML-DSA-87";
        let sig = sign_internal_guarded(&sk, msg, &[0u8; 32]).unwrap();
        assert!(verify_internal(&pk, msg, &sig).unwrap());
    }

    #[test]
    fn wrong_message_rejected() {
        crate::test_support::start_module();
        let xi = [0x01u8; 32];
        let (pk, sk) = keygen_internal_guarded(&xi).unwrap();
        let sig = sign_internal_guarded(&sk, b"original", &[0u8; 32]).unwrap();
        assert!(!verify_internal(&pk, b"tampered", &sig).unwrap());
    }

    #[test]
    fn tampered_signature_rejected() {
        crate::test_support::start_module();
        let xi = [0x55u8; 32];
        let (pk, sk) = keygen_internal_guarded(&xi).unwrap();
        let msg = b"test message";
        let mut sig = sign_internal_guarded(&sk, msg, &[0u8; 32]).unwrap();
        sig[50] ^= 0xFF;
        assert!(!verify_internal(&pk, msg, &sig).unwrap());
    }

    #[test]
    fn deterministic_signing() {
        crate::test_support::start_module();
        let xi = [0xABu8; 32];
        let (_pk, sk) = keygen_internal_guarded(&xi).unwrap();
        let msg = b"deterministic test";
        let s1 = sign_internal_guarded(&sk, msg, &[0u8; 32]).unwrap();
        let s2 = sign_internal_guarded(&sk, msg, &[0u8; 32]).unwrap();
        assert_eq!(s1, s2);
    }

    #[test]
    fn different_seeds_different_keys() {
        crate::test_support::start_module();
        let (pk1, _) = keygen_internal_guarded(&[0x10u8; 32]).unwrap();
        let (pk2, _) = keygen_internal_guarded(&[0x20u8; 32]).unwrap();
        assert_ne!(pk1, pk2);
    }

    #[test]
    fn wrong_key_rejects() {
        crate::test_support::start_module();
        let xi1 = [0x01u8; 32];
        let xi2 = [0x02u8; 32];
        let (pk1, _) = keygen_internal_guarded(&xi1).unwrap();
        let (_, sk2) = keygen_internal_guarded(&xi2).unwrap();
        let msg = b"cross-key test";
        let sig = sign_internal_guarded(&sk2, msg, &[0u8; 32]).unwrap();
        assert!(!verify_internal(&pk1, msg, &sig).unwrap());
    }
}
